window.__BUNDLE__={"generatedAt":"2026-10-27T20:18:15.426857+00:00","recentDays":7,"archiveDays":1825,"recentCutoff":"2026-10-20","archiveCutoff":"2021-10-28","addedToday":0,"addedThisRun":0,"fetchStats":{"hf":357,"arxiv":1530,"total":1887},"freshness":{"latestPaperDate":"2026-10-27","latestPublishedDate":"2026-10-27","latestBatchCount":604,"newInLast24h":662,"newInLast48h":952},"historyTotal":27971,"topicCounts":{"Multi-Agent":3026,"Evaluation":15317,"Planning":2039,"Memory":543,"Code Agent":1121,"Interpretability":940,"Agentic RAG":1518,"Agentic Search":2020,"RL for LLM":1502,"Reasoning":7548,"Hallucination":1250,"Post-Training":3140,"Alignment":3674,"World Model":550,"Tool Use":1433,"Agent Safety":2689,"Computer Use":376,"Reflection":1005,"VLM Training":2191,"LLM Training":3577,"Fine-tuning":4329,"Multimodal Agent":163,"Agent Framework":940,"Error Attribution":180,"Data Engine":558},"count":36,"recentTotal":2727,"archiveCount":0,"archiveTotal":25244,"sources":{"hf":80,"arxiv":2647,"semanticScholar":0},"archiveSources":{"hf":0,"arxiv":0,"semanticScholar":0},"warnings":[],"notes":["archive is split by year under data/archive/ for fast lazy loading; data/history.json keeps the complete database"],"papers":[{"upvotes":330,"url":"https://arxiv.org/abs/2610.33568","date":"2026-10-27","topics":["LLM Training","Tool Use","Evaluation","Fine-tuning"],"title":"Trajectory2Gym: Decision-Grounded Compositional Interaction Synthesis for Tool-Use Agents","announceDate":"2026-10-27","arxiv":"https://arxiv.org/abs/2610.33568","submittedDate":"2026-10-24","hfUrl":"https://huggingface.co/papers/2610.33568","id":"arxiv:2610.33568","source":"hf","tags":["LLM Training","Tool Use","Evaluation","Fine-tuning"],"pdf":"https://arxiv.org/pdf/2610.33568.pdf","authors":["Yihao Hu","Zhihao Wen","Yitong Lin","Siyuan Lu","Pan Wang","Wei Wu","Jiang-Ming Yang","Tao Lin"],"abstract":"Successful tool-use trajectories are not necessarily useful supervision. Even successful interactions may underrepresent multi-step dependencies or contain actions that are unjustified by the information visible to the agent at decision time. We identify two coupled requirements for effective trajectory supervision: compositional coverage, so that important observation-action dependencies are represented, and decision grounding, so that each supervised action is supported by the learner-visible interaction history. We introduce Trajectory2Gym, which constructs executable interactions around under-supported compositional structures and derives supervision only from grounded decisions in their realized executions. Structural-support selection allocates the resulting experience, while parent-normalized supervised fine-tuning preserves the semantic interaction as the unit of training weight."},{"upvotes":237,"url":"https://arxiv.org/abs/2610.34662","date":"2026-10-27","topics":["VLM Training","Evaluation","Multimodal Agent"],"title":"StreamVibe: Proactive Video Agents for Evolving User Intent","announceDate":"2026-10-27","arxiv":"https://arxiv.org/abs/2610.34662","submittedDate":"2026-10-26","hfUrl":"https://huggingface.co/papers/2610.34662","id":"arxiv:2610.34662","source":"hf","tags":["VLM Training","Evaluation","Multimodal Agent"],"pdf":"https://arxiv.org/pdf/2610.34662.pdf","authors":["Chengzhi Liu","Yuxiang Lai","Yuzhe Yang","Yanqing Liu","Jiheng Hou","Yue Cao","Haonan Wang","Ruixi Fan","Lan Wang","Sheng Liu","Songyou Peng","Yale Song","Kevin Qinghong Lin","Xin Eric Wang","Jui-Hsin Lai","Youbao Tang"],"abstract":"Vision-language models are shifting from offline passive understanding toward online proactive interaction. However, prevailing methods largely rely on explicit requests while miss the implicit user intent (e.g., \"where should I click next?\" while a user navigate a website), meanwhile fail to update the state simultaneously as user requests might update continuously. These limitations make them less suited to intent-aware interaction in practical. To address these challenges, we introduce StreamVibe-Bench, a new benchmark serving as testbed for user intent interaction, with 4.1K evaluation samples and 85K training samples spanning explicit, implicit, and dynamic intents. Building on this benchmark, we develop StreamVibe-VL, a streaming proactive model that infers implicit user intents from continuous observations and dynamically tailors its interactions as these intents evolve. We furthe"},{"upvotes":182,"url":"https://arxiv.org/abs/2610.34467","date":"2026-10-27","topics":["LLM Training","Multi-Agent","Reasoning","Evaluation","Fine-tuning"],"title":"DynaFlow: Learning Free-Form Multi-Agent Orchestration","arxiv":"https://arxiv.org/abs/2610.34467","hfUrl":"https://huggingface.co/papers/2610.34467","id":"arxiv:2610.34467","source":"hf","tags":["LLM Training","Multi-Agent","Reasoning","Evaluation","Fine-tuning"],"pdf":"https://arxiv.org/pdf/2610.34467.pdf","authors":["Ruhao Liu","Qi Li","Shizun Wang","Xinchao Wang"],"abstract":"Multi-agent systems often rely on predefined collaboration structures, limiting their ability to adapt to diverse task requirements. We introduce DynaFlow, a framework that integrates free-form executable workflow synthesis into the action space of the main agent. The agent decides when collaboration is needed and generates task-specific programs that coordinate sub-agents through sequential or parallel execution, structured information exchange, and verification. Execution results and traces inform subsequent actions, enabling the agent to adapt collaboration as reasoning progresses. We train only the main agent through supervised fine-tuning on distilled trajectories, followed by refinement on examples filtered for unsupported premises, biased verification, and information-flow defects. All sub-agents remain fixed, separating orchestration learning from executor capability improvement."},{"upvotes":109,"url":"https://arxiv.org/abs/2610.33966","date":"2026-10-27","topics":["Planning","Evaluation"],"title":"InteractiveWorld: A Verifiable Human-Centric Environment for Building Better Interactive MLLM Assistants","announceDate":"2026-10-27","arxiv":"https://arxiv.org/abs/2610.33966","submittedDate":"2026-10-25","hfUrl":"https://huggingface.co/papers/2610.33966","id":"arxiv:2610.33966","source":"hf","tags":["Planning","Evaluation"],"pdf":"https://arxiv.org/pdf/2610.33966.pdf","authors":["Qinsi Wang","Wei Wen","Chong Zhou","Saksham Suri","Zechun Liu","Lemeng Wu","Hai Helen Li","Yiran Chen","Raghuraman Krishnamoorthi","Qi Qian"],"abstract":"People have long dreamed of an assistant that is always there to guide them and remind what they forget, from new dishes to lost keys. Powered by multimodal large language models (MLLMs), egocentric AI assistants on wearable devices are bringing this dream within reach: they see what the user sees and give instructions for user's physical work when necessary. However, testing such assistance is challenging and usually requires real people. The expensive and rare real interaction data leaves a key question unanswered: Can today's MLLMs truly help people in physical world? To answer this question, we propose InteractiveWorld, the first verifiable environment for closed-loop interaction between human and AI assistant. Unlike existing robot-centric simulators, InteractiveWorld lets the assistant guide a human agent who observes the scene, understands instructions, and acts independently. It "},{"upvotes":97,"url":"https://arxiv.org/abs/2610.35845","date":"2026-10-27","topics":["Evaluation"],"title":"Work Agents: Systems, Capabilities, and Optimization","announceDate":"2026-10-27","arxiv":"https://arxiv.org/abs/2610.35845","submittedDate":"2026-10-26","hfUrl":"https://huggingface.co/papers/2610.35845","id":"arxiv:2610.35845","source":"hf","tags":["Evaluation"],"pdf":"https://arxiv.org/pdf/2610.35845.pdf","authors":["Zishan Xu","Enjun Du","Mingqi Gao","Cheng Yang","Junhao Shen","Zirong Chen","Zhiyuan Yao","Yifu Guo","Yuquan Lu","Jinyang Huang","Zhengxi Lu","Siyi Liu","Ziyu Zheng","Yongqi Zhang","Difan Zou","Weiwen Liu"],"abstract":"As foundation models evolve from information generation to digital work execution, agents are increasingly capable of completing complex tasks across tools, applications, and workflows. However, existing research lacks a unified perspective on how agents reliably accomplish delegated work. To address this gap, we present a work-centric, system-level perspective that views work agents as systems combining foundation models and runtime harnesses to execute tasks in stateful workspaces and deliver verifiable outcomes. We introduce two complementary dimensions, work persistence and work openness, to characterize working conditions, and classify digital work into five forms according to task scope and organization. Building on this framework, we identify five core capability families required for reliable work execution and examine approaches to model optimization, harness optimization, and t"},{"upvotes":43,"url":"https://arxiv.org/abs/2610.33956","date":"2026-10-27","topics":["Evaluation"],"title":"Continual Learning Exam: Benchmarking Long-Horizon RSI and Experiential Learning in LLM Agents","announceDate":"2026-10-27","arxiv":"https://arxiv.org/abs/2610.33956","submittedDate":"2026-10-25","hfUrl":"https://huggingface.co/papers/2610.33956","id":"arxiv:2610.33956","source":"hf","tags":["Evaluation"],"pdf":"https://arxiv.org/pdf/2610.33956.pdf","authors":["Haoyu Zhao","Sitian Tu","Yuxuan Huang","Huichi Zhou","Zhangyue Yin","Jiahao Huang","Jingyuan Xu","Tianmiao Shi","Jin Shi","Nianxi Zhang","Yangmiao Zhang","Zhuolang Chan","Huiyan Hu","Chenchao Sheng","Yaqing Luo","Yue Chen","Huaxiu Yao","Meng Fang","Jun Wang"],"abstract":"Continual learning is the ability of LLM agents to improve over time by acquiring, refining, and applying knowledge from experience while retaining useful prior knowledge. It is essential for agents learning over long time horizons, yet current evaluations largely assess individual task performance rather than improvement through accumulated experience. We introduce Continual Learning Exam (CLE), a large-scale benchmark developed by 50+ domain experts to measure experience-driven improvement in realistic professional workflows. CLE comprises 120 human-authored tasks, each organised as a five-level ladder, yielding 600 levels spanning 89 professional roles across 12 occupational domains. Agents must pass each level to unlock the next, with later levels building on experience accumulated during earlier assignments. An evaluation agent assesses each submission against human-authored rubrics"},{"upvotes":42,"url":"https://arxiv.org/abs/2610.33135","date":"2026-10-27","topics":["Evaluation","Alignment"],"title":"WorldCast: World-Consistent Character Video Generation with Large-Angle Camera Control","announceDate":"2026-10-27","arxiv":"https://arxiv.org/abs/2610.33135","submittedDate":"2026-10-23","hfUrl":"https://huggingface.co/papers/2610.33135","id":"arxiv:2610.33135","source":"hf","tags":["Evaluation","Alignment"],"pdf":"https://arxiv.org/pdf/2610.33135.pdf","authors":["Lei Cao","Yu Liu","Wenhua Liao","Peng Zhang","Fei Wang","Hao Zhang","Jiajun Le","Daiguo Zhou","Jian Luan","Jiayi Ma"],"abstract":"Precise camera control is essential for cinematic character video generation, yet existing methods struggle to follow large-angle trajectories with combined rotation, translation, and radius variation from arbitrary initial azimuths. Such viewpoint changes also reveal character regions unseen in the initial frame, causing geometric distortions, appearance degradation, and identity drift. To systematically study these coupled challenges, we introduce CLACT, a large-scale Character-centric dataset and benchmark covering diverse Large-Angle Camera Trajectories, with accurate camera geometry and multi-view character observations for training and evaluation. We further propose WorldCast, a framework for world-consistent character video generation under diverse large-angle camera motions. Specifically, we back-project the initial frame into a 3D point cloud using estimated depth, align the poi"},{"upvotes":38,"url":"https://arxiv.org/abs/2610.34415","date":"2026-10-27","topics":["Planning"],"title":"Spatial Audio Generation and Editing with Executable Plans and Self-Distilling Transfusion","announceDate":"2026-10-27","arxiv":"https://arxiv.org/abs/2610.34415","submittedDate":"2026-10-25","hfUrl":"https://huggingface.co/papers/2610.34415","id":"arxiv:2610.34415","source":"hf","tags":["Planning"],"pdf":"https://arxiv.org/pdf/2610.34415.pdf","authors":["Kam Man Wu","Yu Zhang","Pengjun Fang","Mingfei Chen","Weijia Chen","Zeyue Tian","Qifeng Chen"],"abstract":"Spatial audio authoring coordinates source decisions with soundfield synthesis. For editing, plans specify what to change and retain, while reference audio supplies further acoustic detail. We present AMBIT, a unified framework for native First-Order Ambisonics (FOA) generation and editing with three connected contributions. First, a shared Transfusion backbone couples autoregressive planning with rectified-flow rendering through executable ScenePlans that specify source content, activity, and 3D trajectories. For editing, the plan describes the full target scene, including retained sources; contrastive features ground the requested change, while full reference latents supply residual acoustic detail for preservation. Second, an FOA-aware continuous VAE combines shared-decoder omnidirectional recovery, asymmetric grouped KL, and spatial covariance matching to preserve content and inter-c"},{"upvotes":21,"url":"https://arxiv.org/abs/2610.34238","date":"2026-10-27","topics":["Tool Use","Evaluation"],"title":"$Δτ$-Bench: Pushing Agents Toward a Moving Capability","announceDate":"2026-10-27","arxiv":"https://arxiv.org/abs/2610.34238","submittedDate":"2026-10-25","hfUrl":"https://huggingface.co/papers/2610.34238","id":"arxiv:2610.34238","source":"hf","tags":["Tool Use","Evaluation"],"pdf":"https://arxiv.org/pdf/2610.34238.pdf","authors":["Shuofei Qiao","Xuanguang Pan","Yijun Chen","Wendi Feng","Bin Wu","Runnan Fang","Yuqi Zhu","Shumin Deng","Emine Yilmaz"],"abstract":"In this paper, we introduce $Δτ$-Bench, an executable agent benchmark that models the structural evolution of large tool ecosystems. In $Δτ$-Bench, independently evolving services continually reshape how tasks can be accomplished: familiar tools may disappear or be replaced, while more efficient alternatives emerge amid overlapping functionality and noisy documentation. Against this moving capability frontier, we evaluate whether agents can proactively discover efficient tool-use paths and promptly revise their accumulated procedural knowledge, bringing together demands that existing benchmarks fail to examine. $Δτ$-Bench comprises 1,588 validated multi-turn tasks across 42 domains and six successive ecosystem states generated through capability-preserving transformations. Our evaluation shows that even the strongest evaluated model or harness achieves only 42.3% task success, while init"},{"upvotes":20,"url":"https://arxiv.org/abs/2610.33472","date":"2026-10-27","topics":["LLM Training","Evaluation","Fine-tuning"],"title":"Qwen-Image-PE: Learning Visual Design for Text-to-Image Prompt Enhancement","announceDate":"2026-10-27","arxiv":"https://arxiv.org/abs/2610.33472","submittedDate":"2026-10-24","hfUrl":"https://huggingface.co/papers/2610.33472","id":"arxiv:2610.33472","source":"hf","tags":["LLM Training","Evaluation","Fine-tuning"],"pdf":"https://arxiv.org/pdf/2610.33472.pdf","authors":["Zekai Zhang","Yanran Zhang","Shengming Yin","Yan Shu","Zhening Liu","Bingxuan Zhao","Chenyang Zhu","Donghao Zhou","Jiahao Li","Jiahao Wang","Jie Zhang","Kaiyuan Gao","Kun Yan","Lihan Jiang","Ningyuan Tang","Qihang Ai","Rui Song","Shuo Cao","Xiao Xu","Xiaoyue Chen","Yuxiang Chen","Zhendong Wang","Zhouyang Li","Zihao Liu","Zikai Zhou","Bo Zheng","Huishuai Zhang","Dongyan Zhao","Chenfei Wu"],"abstract":"Learning visual design is essential for prompt enhancement (PE) to turn underspecified user requests into coherent visual specifications for text-to-image (T2I) generation. Existing methods preserve user intent and improve overall visual appeal, with less explicit emphasis on fine-grained design dimensions. To address this gap, we introduce Qwen-Image-PE, which learns visual design through two-stage training. Supervised fine-tuning with Caption-Based Reverse Distillation (CRD) uses dense captions of well-designed images as design supervision. Reinforcement learning with Groupwise Design Reward (GDR) jointly compares all candidate images for the same request to refine lighting, composition, layout, and detail. On Qwen-Image-Bench with Qwen-Image-2.1, Qwen-Image-PE-397B improves over original requests by 7.81 points, while Qwen-Image-PE-9B outperforms all evaluated PE baselines. Further ev"},{"upvotes":18,"url":"https://arxiv.org/abs/2610.35193","date":"2026-10-27","topics":["Evaluation","Alignment","Reflection"],"title":"Trustworthy Recursive Self-Improvement in the Era of Large Models: Foundation, Risks, Evaluation and Open Challenges","announceDate":"2026-10-27","arxiv":"https://arxiv.org/abs/2610.35193","submittedDate":"2026-10-26","hfUrl":"https://huggingface.co/papers/2610.35193","id":"arxiv:2610.35193","source":"hf","tags":["Evaluation","Alignment","Reflection"],"pdf":"https://arxiv.org/pdf/2610.35193.pdf","authors":["Jiayue Pu","Ang Gao","Jinyi Bai","Qipeng Wang","Tongyu Wen","Jiahao Zhao","Keyu Qu","Junhao Zhang","Chenglei Shen","Zhongxiang Sun","Jun Xu","Xiao Zhang"],"abstract":"AI systems built around large models increasingly use experience and feedback to make persistent changes to models, prompts, memories, tools, and workflows. Recursive self-improvement (RSI) extends this process to inductive biases and to the mechanisms that govern future updates, which can themselves be revised and reused across improvement cycles. Yet self-modification alone does not guarantee trustworthy improvement. Reported gains may reflect flawed evaluations, previously acquired capabilities may deteriorate, and compliance with behavioral constraints may weaken. Compromised artifacts or sensitive information may also persist in successor systems. Changes to improvement mechanisms may invalidate earlier verification results and make human oversight less effective. This survey presents an operational definition and process framework for RSI and organizes the requirements for trustwor"},{"upvotes":12,"url":"https://arxiv.org/abs/2610.35518","date":"2026-10-27","topics":["Post-Training","Reasoning","RL for LLM"],"title":"S3AC: Stabilized, Selective, and Scalable Actor-Critic for LLM Reasoning","announceDate":"2026-10-27","arxiv":"https://arxiv.org/abs/2610.35518","submittedDate":"2026-10-26","hfUrl":"https://huggingface.co/papers/2610.35518","id":"arxiv:2610.35518","source":"hf","tags":["Post-Training","Reasoning","RL for LLM"],"pdf":"https://arxiv.org/pdf/2610.35518.pdf","authors":["Shuo Shen","Guangran Cheng","Chengqi Lyu","Xiangsen Wang","Yanan Sun","Wenwei Zhang"],"abstract":"Critic-free methods are widely used in reinforcement learning with verifiable rewards (RLVR) for long chain-of-thought (CoT) reasoning, avoiding difficult and costly critic training. Common alternatives lack token-level credit assignment and typically rely on grouped rollouts to estimate prompt-specific baselines. A critic can address both limitations, but long-CoT critic training is hindered by insufficient coverage of trajectories with diverse lengths and early gradients dominated by the newly initialized value head. We introduce S3AC (Stabilized, Selective, and Scalable Actor-Critic) for LLM reasoning, built around a practical critic-training recipe. The trained critic provides token-specific advantages and prompt-specific baselines. Using the prompt-level baseline to estimate difficulty, we propose Difficulty-Aware Prompt Sampling (DAPS). DAPS combines this estimate with outcome hist"},{"upvotes":10,"url":"https://arxiv.org/abs/2610.33845","date":"2026-10-27","topics":["Agentic Search","Evaluation"],"title":"Build, Don't Play: Self-Improving LLM Research Agents Develop a Hearthstone Battlegrounds AI That Rivals Top Players","announceDate":"2026-10-27","arxiv":"https://arxiv.org/abs/2610.33845","submittedDate":"2026-10-24","hfUrl":"https://huggingface.co/papers/2610.33845","id":"arxiv:2610.33845","source":"hf","tags":["Agentic Search","Evaluation"],"pdf":"https://arxiv.org/pdf/2610.33845.pdf","authors":["Changlian Ma","Limin Wang"],"abstract":"Can LLM agents carry a hard real-world problem from raw data to a system that holds its own against people? We study this in Hearthstone Battlegrounds, an eight-player auto-battler with stochastic shops and battles, hidden information and nearly a thousand interacting cards. We present AutoTavern, a self-improving research system: specialised LLM research agents share a typed research memory, every claim passes verification gates, and live games close the loop, so the agents improve the simulator, opponents and policy and, from the same feedback, their own research process; a human sets goals and rules on ambiguous mechanics. In 20 days AutoTavern built TavernGym, the first faithful, full-content reproduction of the live game, and delivered 23 versions of TavernAgent, trained with PPO against opponents calibrated to real games. TavernAgent plays complete games on the live ladder by itsel"},{"upvotes":9,"url":"https://arxiv.org/abs/2610.35385","date":"2026-10-27","topics":["Planning","Code Agent","Evaluation"],"title":"EmbodiedLab: Benchmarking Embodied Agents That Act to Know","arxiv":"https://arxiv.org/abs/2610.35385","hfUrl":"https://huggingface.co/papers/2610.35385","id":"arxiv:2610.35385","source":"hf","tags":["Planning","Code Agent","Evaluation"],"pdf":"https://arxiv.org/pdf/2610.35385.pdf","authors":["Hongcheng Gao","Zelin Zheng","Alex Zhou","Jay Zhu","Shijia Ge","Yazhe Wang","Xiping Li","Jianshu Zeng","Di Wu","Xuan Shangguan","Yexing Wan","Lingyu He","Yongli Wang","Xiaohan Yu","Zhiqi Jia","Yue Liu","Bryan Hooi","Yinpeng Dong","Wentao Zhang","Sihang Wu","Xiao He"],"abstract":"Embodied agents are expected to accomplish real-world goals by deciding for themselves how and when to interact with their surroundings. For many such goals, changing the physical state of the world is the means rather than the end: the agent changes the state of a system through interaction, observes the feedback, and explores until it either achieves the goal itself (e.g., discovering physical laws) or learns what the goal requires; it acts to know. Manipulation benchmarks stop at acting to change, with the target state given; scientific discovery benchmarks evaluate knowing but replace physical experimentation with symbolic actions or numerical queries. We introduce EmbodiedLab, a benchmark in which a robot must act to know. Quantitative science experiments make this setting controllable: the parameters of the system are resampled for every instance, so the result cannot be known in a"},{"upvotes":9,"url":"https://arxiv.org/abs/2610.34356","date":"2026-10-27","topics":["LLM Training","VLM Training","Evaluation"],"title":"RynnVLA-Latent: Scaling Robotic Manipulation Foundation Models with 3D-Grounded Latent Actions","arxiv":"https://arxiv.org/abs/2610.34356","hfUrl":"https://huggingface.co/papers/2610.34356","id":"arxiv:2610.34356","source":"hf","tags":["LLM Training","VLM Training","Evaluation"],"pdf":"https://arxiv.org/pdf/2610.34356.pdf","authors":["Haoyu Zhao","Xingyue Zhao","Zhian Su","Bohan Hou","Yinzhou Tang","Fengyi Wang","Kehan Li","Yuming Jiang","Siteng Huang","Xin Li","Zhenyu Zeng","Mingxiu Chen","Deli Zhao","Zhongyu Li"],"abstract":"Scaling vision-language-action (VLA) models is constrained by scarce action-labeled demonstrations and incompatible control spaces across robot embodiments. We present RynnVLA-Latent, a framework that turns heterogeneous interaction videos into scalable supervision for robot policy pretraining. At its core, RynnLAM learns continuous, 3D-grounded latent actions from visual transitions without requiring native robot controls. By combining residual future-feature prediction, camera-compensated 3D-flow supervision, and camera-motion decoupling, RynnLAM encourages representations that capture control-relevant motion rather than appearance changes alone. We apply RynnLAM to 30.1K hours of human, robot, and simulation videos, producing 745.52M latent-action descriptors. RynnVLA-Latent then learns to predict latent-action chunks from visual observations and language through flow matching, before"},{"upvotes":7,"url":"https://arxiv.org/abs/2610.34634","date":"2026-10-27","topics":["Computer Use","Evaluation"],"title":"AgentProofBench: Benchmarking Reusable Verifiers for Web Agents","announceDate":"2026-10-27","arxiv":"https://arxiv.org/abs/2610.34634","submittedDate":"2026-10-25","hfUrl":"https://huggingface.co/papers/2610.34634","id":"arxiv:2610.34634","source":"hf","tags":["Computer Use","Evaluation"],"pdf":"https://arxiv.org/pdf/2610.34634.pdf","authors":["Jingjie Ning","Xueqi Li","Yi Lu","Yibo Kong"],"abstract":"Reusable Web-agent verification requires a rule to follow changing requirements and support subsequent execution. We introduce AgentProofBench, which connects paired tests of a frozen acceptance rule to execution from identical saved openings. The resource spans 97 tasks, 79 families, and four Web services. Experiments with DeepSeek Flash/Pro establish two linked measurements. Across 48 families, complete-panel and decision-replay tests retain 82/96 Flash and 79/96 Pro source programs; paired reuse-rebuild BA intervals are [-5.47, 1.57] and [-10.16, 0.00] percentage points. Across 22 execution families, deployment-state panel correctness separates program assignments whose two saved openings are both delivered correctly: 32/33 assignments with error-free panels, versus 1/11 with panel errors. All reference-defined program-gate regressions and withheld deliveries occur in the latter group"},{"upvotes":7,"url":"https://arxiv.org/abs/2610.34654","date":"2026-10-27","topics":["Reasoning","Evaluation"],"title":"Thinking-in-Bets at Test Time Reduces Sycophantic Revisions in LLM Agents","announceDate":"2026-10-27","arxiv":"https://arxiv.org/abs/2610.34654","submittedDate":"2026-10-26","hfUrl":"https://huggingface.co/papers/2610.34654","id":"arxiv:2610.34654","source":"hf","tags":["Reasoning","Evaluation"],"pdf":"https://arxiv.org/pdf/2610.34654.pdf","authors":["Nghi D. Q. Bui"],"abstract":"Language model agents often abandon correct work when a user challenges it, yet simply telling them to stand firm makes them ignore real mistakes. Once an agent reads a complaint, it tends to discount its own earlier checks in order to agree with the user. We introduce Thinking-in-Bets, a training-free method in which an agent writes a short private record of its main claims, the checks supporting them, and its confidence before reading user feedback. When challenged, the agent consults this Claim Checklist to keep verified work intact while investigating uncertain or newly challenged parts. We evaluate five Gemini models (3.5 Flash-Lite, 3.5 Flash, 3.6 Flash, 3.8 Flash, and 4.0 Argon) across eight benchmarks: SWE-Together, SWE-Interact, and DeepSWE for software engineering, Agents' Last Exam for professional reports, Humanity's Last Exam and SycEval for academic reasoning, Vals Finance "},{"upvotes":6,"url":"https://arxiv.org/abs/2610.33503","date":"2026-10-27","topics":["Agentic Search","LLM Training","Reasoning","Evaluation","Fine-tuning"],"title":"Novel or Not? PatEx-Gym: Agentic Prior-Art Search for Novelty Assessment in Patent Examination","announceDate":"2026-10-27","arxiv":"https://arxiv.org/abs/2610.33503","submittedDate":"2026-10-24","hfUrl":"https://huggingface.co/papers/2610.33503","id":"arxiv:2610.33503","source":"hf","tags":["Agentic Search","LLM Training","Reasoning","Evaluation","Fine-tuning"],"pdf":"https://arxiv.org/pdf/2610.33503.pdf","authors":["Qiyao Wang","Xinyi Chen","Hongbo Wang","Jiayuan Lu","Jianhang Li","Minghuan Tan","Yuan Lin","Min Yang"],"abstract":"Patent examination is a challenging real-world task that requires agents to discover sparse prior art, iteratively refine queries, inspect technical evidence, and produce novelty assessments documented in Office Actions (OAs) across heterogeneous scientific and technical domains. However, existing benchmarks largely focus on static and limited candidate sets, leaving the full search--reasoning--assessment process underexplored. We present PatEx-Gym, the first framework for developing and evaluating agents for patent examination, which integrates three components. First, PatEx-Bench provides 1K realistic examination tasks, two large-scale retrieval corpora containing over 1M patents and 52K scientific papers, and a harness runtime supporting iterative search, document visits, reasoning, and OA generation. Second, we introduce PASS, an annotation-free Prior-Art Agentic Search Trajectory Sy"},{"upvotes":4,"url":"https://arxiv.org/abs/2610.33608","date":"2026-10-27","topics":["Hallucination","Evaluation"],"title":"Mycelium: A Meta-Study of Hallucination Detection Across Provenance, Typology, and Granularities","announceDate":"2026-10-27","arxiv":"https://arxiv.org/abs/2610.33608","submittedDate":"2026-10-24","hfUrl":"https://huggingface.co/papers/2610.33608","id":"arxiv:2610.33608","source":"hf","tags":["Hallucination","Evaluation"],"pdf":"https://arxiv.org/pdf/2610.33608.pdf","authors":["Julia Belikova","Elisei Rykov"],"abstract":"Hallucination detection is increasingly important for evaluating and deploying large language models. However, existing methods are often compared across benchmarks that define and measure hallucination in substantially different ways, making reported scores difficult to interpret across settings. We study hallucination detection as a benchmark-conditioned measurement problem and organize existing benchmarks along three axes: provenance, which describes how model outputs and evidence conditions are obtained; typology, which captures the factuality and faithfulness failures represented by benchmark labels; and granularity, which specifies the unit at which hallucinations are annotated, predicted, and evaluated. Using this framework, we analyze how benchmark construction, annotation, and evaluation choices shape the underlying prediction task, and relate detector mechanisms and assumptions"},{"upvotes":4,"url":"https://arxiv.org/abs/2610.34241","date":"2026-10-27","topics":["Evaluation"],"title":"Beyond Benchmarks: Can Small Open-Weight Models Get Real Coding Work Done?","announceDate":"2026-10-27","arxiv":"https://arxiv.org/abs/2610.34241","submittedDate":"2026-10-25","hfUrl":"https://huggingface.co/papers/2610.34241","id":"arxiv:2610.34241","source":"hf","tags":["Evaluation"],"pdf":"https://arxiv.org/pdf/2610.34241.pdf","authors":["Vaibhav Jain"],"abstract":"Making an open-weight language model generate text is not the same as making it finish coding work. This retrospective empirical systems experience report follows my engineering work from July to October 2026 across coding clients, model-specific serving recipes, vLLM, SGLang, llama.cpp, and MLX. Models behind a nominally compatible endpoint still differed in tool-call formatting, turn control, context behavior, cache reuse, and reliability. A served model, coherent text, executed tool calls, and code that passes independent behavioral checks proved to be distinct levels of progress. The evidence includes 4,165 coding-agent gateway turns from my own sessions, 623 debug jobs, and three separate delegation studies with hidden behavioral checks and a fixed Claude Opus 5.5 parent. Saved cold-prefix requests had a median time to first token of about 69.4 s, versus 2.8 s for high-reuse request"},{"upvotes":3,"url":"https://arxiv.org/abs/2610.35434","date":"2026-10-27","topics":["Reflection"],"title":"Skill$^{\\infty}$: Recursive Self-Improvement for Agent Skill Optimization","announceDate":"2026-10-27","arxiv":"https://arxiv.org/abs/2610.35434","submittedDate":"2026-10-26","hfUrl":"https://huggingface.co/papers/2610.35434","id":"arxiv:2610.35434","source":"hf","tags":["Reflection"],"pdf":"https://arxiv.org/pdf/2610.35434.pdf","authors":["Wangcheng Tao","Zhanglu Yan","Han Wu","Weng-Fai Wong"],"abstract":"Recursive self-improvement (RSI), in which a system also improves the way it improves, is a long-standing aspiration on the path to AGI. Language agents increasingly store procedural knowledge in reusable skills. Optimizing skills offers a direct way to achieve RSI, because the optimization procedure itself can be encoded as a skill. Existing skill optimizers, however, follow a hand-designed procedure. Even methods that evolve a meta-skill confine it to a fixed pipeline and relearn it for each task. We present Skill$^{\\infty}$, which makes skill optimization recursively self-improving: a meta agent follows a meta-skill to optimize task skills and optimizes the meta-skill itself using the same procedure. The optimization is agent-led. The meta agent diagnoses execution traces, proposes candidates, requests independent reviews, and allocates the search budget. The meta-skill defines these "},{"upvotes":1,"url":"https://arxiv.org/abs/2610.34149","date":"2026-10-27","topics":["Post-Training","Reasoning","Evaluation","Fine-tuning"],"title":"Humans in Space: Can MLLMs Construct Human-Centric Spatial Understanding via Active Exocentric Exploration?","announceDate":"2026-10-27","arxiv":"https://arxiv.org/abs/2610.34149","submittedDate":"2026-10-25","hfUrl":"https://huggingface.co/papers/2610.34149","id":"arxiv:2610.34149","source":"hf","tags":["Post-Training","Reasoning","Evaluation","Fine-tuning"],"pdf":"https://arxiv.org/pdf/2610.34149.pdf","authors":["Tianchen Guo","Tengyue Zhang","Chen Liu","Ling Chen","Xin Yu"],"abstract":"While Multimodal Large Language Models (MLLMs) excel at zero-shot reasoning, their spatial capabilities are primarily evaluated through static, passive observation. In complex, human-centric scenes, occlusion often hides crucial geometric evidence, and passive benchmarks force models to guess rather than recognize their own visual uncertainty. To bridge this gap, we introduce SATE-Bench, a novel interactive benchmark comprising 316 real-world scenes and 2,525 multi-turn QA pairs to evaluate visual self-awareness and active exocentric view-exploration. It combines a Passive multi-view control with an Active exploration setting, where models start from a severely occluded view and must iteratively query adjacent viewpoints until they gather enough evidence to fully ``sate'' the question, scored by a step-penalized efficiency reward. Evaluating state-of-the-art MLLMs reveals that they termi"},{"upvotes":32,"url":"https://arxiv.org/abs/2610.33413","date":"2026-10-27","topics":["Evaluation"],"title":"AV-FABLE: Audio-Visual Manipulation Forensics in Long-Form Videos","announceDate":"2026-10-27","arxiv":"https://arxiv.org/abs/2610.33413","submittedDate":"2026-10-24","hfUrl":"https://huggingface.co/papers/2610.33413","id":"arxiv:2610.33413","source":"arxiv","tags":["Evaluation"],"pdf":"https://arxiv.org/pdf/2610.33413.pdf","authors":["Yuesheng Huang","Hoi Fan Au","Jiaqi Hou","Ruicheng Zhang","Jiarui He","Haocheng Yang","Bin Hu","Kewei Zhang","Weijian Deng","Jun Zhou","Xiu Li"],"abstract":"Localized AI manipulations in long-form videos often affect brief events within otherwise authentic content, making video-level classification insufficient for forensic analysis. Existing audio-visual deepfake benchmarks largely focus on short talking-head clips, while long-form temporal forensics remains predominantly visual. We introduce AV-FABLE, a dual-timeline benchmark for sparse manipulations in open-scene long-form audio-visual videos. AV-FABLE contains 16,650 pristine--manipulated twin pairs (998 hours) created with 27 editing configurations, with separate audio and visual timelines that enable modality-specific temporal localization and expose errors hidden by joint-timeline evaluation. On AV-FABLE, zero-shot prompting of audio-visual large language models (AV-LLMs) yields near-chance detection and poor temporal localization. In contrast, supervised readouts of their frozen per"},{"upvotes":12,"url":"https://arxiv.org/abs/2610.33024","date":"2026-10-27","topics":["Evaluation"],"title":"Evolving to Match Capabilities: Improving Harness Self-Evolution via Skill Adaptation","announceDate":"2026-10-27","arxiv":"https://arxiv.org/abs/2610.33024","submittedDate":"2026-10-10","hfUrl":"https://huggingface.co/papers/2610.33024","id":"arxiv:2610.33024","source":"arxiv","tags":["Evaluation"],"pdf":"https://arxiv.org/pdf/2610.33024.pdf","authors":["Zhihao Yang","Haojin Wang","Juncheng Wu","Kuan Zhang","Yukun Chen","Run Luo","Yaojie Lu","Yuyin Zhou","Lu Wang","Xianpei Han"],"abstract":"Harness self-evolution offers a practical route for LLM agents to improve from execution experience without updating model parameters. Its effectiveness depends on whether models can successfully act on the guidance provided by their harnesses. However, we find that harness benefits are not uniform across model capabilities: skills that improve stronger models can provide little benefit or even degrade performance for weaker ones. Across seven models and three benchmarks, we identify 103 task-skill pairs where skills improve GPT-5.6-luna by 31.1 points but degrade Gemma-4-E4B by 8.8 points. In 86% of failed weak-model runs, the violated requirement is already stated in the skill. This motivates skill adaptation: reformulating existing skills to match the executor's capabilities and make their guidance easier to execute. To achieve this, we diagnose failures in tool execution, context man"},{"upvotes":5,"url":"https://arxiv.org/abs/2610.33861","date":"2026-10-27","topics":["Evaluation"],"title":"ReGE: Stronger Agents through Experience Synthesis","announceDate":"2026-10-27","arxiv":"https://arxiv.org/abs/2610.33861","submittedDate":"2026-10-24","hfUrl":"https://huggingface.co/papers/2610.33861","id":"arxiv:2610.33861","source":"arxiv","tags":["Evaluation"],"pdf":"https://arxiv.org/pdf/2610.33861.pdf","authors":["Jiarong Liang","Yubo Wang","Zijie Liu","Yuxuan Zhang","Ping Nie","Wenhu Chen"],"abstract":"Repeated attempts at interactive tasks uncover facts, useful operations, and failures that can inform subsequent execution. We introduce ReGE, a framework for turning this recorded experience into guidance for a fresh attempt. Its main implementation, ReGE-Syn, uses a single coach call to jointly synthesize bounded execution records and available artifacts into self-contained guidance, connecting task-specific findings with proposed actions and relevant pitfalls. A student starts from the task's initial environment state and adapts this guidance to current observations. Source generation, synthesis, and student execution use the same base model, without parameter updates or a stronger teacher. Across four benchmarks, ReGE improves accuracy by an average of 9.9 percentage points for GPT and 8.8 percentage points for Claude compared with unguided execution. On matched BrowseComp-Plus subse"},{"upvotes":4,"url":"https://arxiv.org/abs/2610.34735","date":"2026-10-27","topics":["Evaluation"],"title":"iPrefBench: A User-Centric Benchmark for Personalized Mobile Use Agents","announceDate":"2026-10-27","arxiv":"https://arxiv.org/abs/2610.34735","submittedDate":"2026-10-26","hfUrl":"https://huggingface.co/papers/2610.34735","id":"arxiv:2610.34735","source":"arxiv","tags":["Evaluation"],"pdf":"https://arxiv.org/pdf/2610.34735.pdf","authors":["Yuting Ning","Ruijia Cheng","Sushobhan Ghosh","Peitong Duan","HungShi Lin","Abhishek Sundararajan","Shreyash Pandey","Huan Sun","Jeffrey Nichols","Eldon Schoop"],"abstract":"An agent that truly knows and acts on behalf of its user has been a long-standing promise of AI assistants. Computer-use agents bring this promise within reach by capably executing fully specified tasks across apps. However, real-world user requests are often underspecified. To act correctly for the particular user, an agent must infer some missing information from the user's activity history and ask for other information that only the user can provide, without making unsupported assumptions or burdening the user with unnecessary questions. We present iPrefBench, a benchmark for evaluating the infer and ask capabilities of personal mobile-use agents in an executable iOS environment with an interactive simulated user. Grounded in a coherent persona with 3,051 past activity events, iPrefBench comprises 130 underspecified user tasks across 26 apps. Each omitted user-dependent requirement is"},{"upvotes":3,"url":"https://arxiv.org/abs/2610.33718","date":"2026-10-27","topics":["VLM Training","Evaluation","Fine-tuning"],"title":"RoboJev: An Open Vision-Language Judge for Robot Success Detection","announceDate":"2026-10-27","arxiv":"https://arxiv.org/abs/2610.33718","submittedDate":"2026-10-24","hfUrl":"https://huggingface.co/papers/2610.33718","id":"arxiv:2610.33718","source":"arxiv","tags":["VLM Training","Evaluation","Fine-tuning"],"pdf":"https://arxiv.org/pdf/2610.33718.pdf","authors":["Josef Liyanjun Chen"],"abstract":"Many robot manipulation videos do not indicate whether the task was successfully completed. RoboJev-27B is an open-weight vision-language model that takes a task instruction, 10 frames of a manipulation attempt, and (if available) final frames from auxiliary cameras and predicts whether the robot accomplished the task. RoboJev-27B is a variant of JEV-27B-VL, trained with a rank-32 LoRA adapter on the language model only (keeping the vision encoder frozen) using 52,598 episode records. It also uses a source-specific KL penalty that applies only to research data, anchoring predictions closer to the original model on those sources. It uses a calibrated two-token readout that outputs success/failure probabilities in a single forward pass. On 268 held-out episodes of the same robot model (SO-101), RoboJev-27B attains 95.2% balanced accuracy and 0.993 AUROC. It also generalises to episodes col"},{"upvotes":3,"url":"https://arxiv.org/abs/2610.21073","date":"2026-10-27","topics":["Code Agent","Evaluation"],"title":"Skip the Compressor: Coding Agents Fix More Issues When They Pick Whole Files","announceDate":"2026-10-27","arxiv":"https://arxiv.org/abs/2610.21073","submittedDate":"2026-10-15","hfUrl":"https://huggingface.co/papers/2610.21073","id":"arxiv:2610.21073","source":"arxiv","tags":["Code Agent","Evaluation"],"pdf":"https://arxiv.org/pdf/2610.21073.pdf","authors":["Xiaocong Yang","Rishit Chatterjee","Himanshu Udupi","Vikram Ramavarapu","ChengXiang Zhai"],"abstract":"A coding agent works on repositories that can be far larger than its context window can hold. Prompt compressors and retrievers offer solutions to this problem, but patching an issue needs two things at once: the files that must change, and their code exactly as written, since the model must reproduce the lines it edits. Retrievers rank code by its similarity to the issue rather than by whether it must change, and compressors delete text to fit the budget. We show that at an equal token budget, an agent resolves more issues when the budget goes to choosing which files to show verbatim, as our simple selector CQ2-CARE does, than when it goes to pruning tokens or retrieving chunks. We fit every context to the same per-issue budget on 300 recent SWE-rebench issues and grade each patch with the benchmark's tests. With GPT-5.6 and Claude Opus 5, CQ2-CARE resolves 43.7% and 46.7% of the issues"},{"upvotes":3,"url":"https://arxiv.org/abs/2610.35328","date":"2026-10-27","topics":["Reasoning","Evaluation"],"title":"Constrained Decoding: Harmful or Beneficial? Revisiting Its Impact on LLM Performance","announceDate":"2026-10-27","arxiv":"https://arxiv.org/abs/2610.35328","submittedDate":"2026-10-26","hfUrl":"https://huggingface.co/papers/2610.35328","id":"arxiv:2610.35328","source":"arxiv","tags":["Reasoning","Evaluation"],"pdf":"https://arxiv.org/pdf/2610.35328.pdf","authors":["Ngoc Trinh Hung Nguyen","Alonso Silva","Armen Aghasaryan","Mehwish Alam"],"abstract":"Constrained decoding guarantees that Large Language Models (LLMs) produce outputs conforming to predefined formats, but is often assumed to inherently degrade reasoning. We examine this assumption through a taxonomy of three constraint types: \\emph{format constraints}, which enforce output structure; \\emph{validity constraints}, which mask invalid answer; and \\emph{reasoning constraints}, which restrict reasoning trajectories. We theoretically show that appropriate constraints can preserve or improve performance by eliminating invalid paths. Across four model families and eleven open-source models, causal ablations on diverse benchmarks using state-of-the-art constrained decoding strategies reveal that apparent performance degradation largely stems from non-equivalent prompting and output formats rather than from decoder-level masking. Meanwhile, validity constraints improve reliability "},{"upvotes":2,"url":"https://arxiv.org/abs/2610.33732","date":"2026-10-27","topics":["Agentic RAG","Agentic Search"],"title":"Trust Mechanisms for Offline Generative AI at the Edge: A Connectivity-Regime Framework and an Empirical Study on a Raspberry Pi 5","announceDate":"2026-10-27","arxiv":"https://arxiv.org/abs/2610.33732","submittedDate":"2026-10-24","hfUrl":"https://huggingface.co/papers/2610.33732","id":"arxiv:2610.33732","source":"arxiv","tags":["Agentic RAG","Agentic Search"],"pdf":"https://arxiv.org/pdf/2610.33732.pdf","authors":["Georgios Feretzakis","Alexandros Papaspyridis"],"abstract":"Generative AI and large language models (LLMs) are moving into the Internet of Things, yet most deployments assume cloud connectivity, and many IoT settings have intermittent, restricted, or no connectivity. We propose a connectivity-regime framework (C0-C4), a taxonomy of inference-time trust mechanisms, and signed, versioned knowledge packs as the update channel for disconnected regimes, and evaluate them on a Raspberry Pi 5 running fully local retrieval-augmented generation under network isolation, with three Qwen2.5 model sizes, three context sizes, and 300 SQuAD 2.0 questions. An empirically calibrated retrieval-score gate detects knowledge gaps almost perfectly (AUROC 0.97) but in-topic unanswerable questions poorly (0.68). A deterministic output validator converts malformed outputs into explicit abstentions with no observed loss of correct answers, while the NLI-based verifier we "},{"upvotes":2,"url":"https://arxiv.org/abs/2610.34577","date":"2026-10-27","topics":["Evaluation"],"title":"Rethinking Verification in Agent Harnesses","announceDate":"2026-10-27","arxiv":"https://arxiv.org/abs/2610.34577","submittedDate":"2026-10-25","hfUrl":"https://huggingface.co/papers/2610.34577","id":"arxiv:2610.34577","source":"arxiv","tags":["Evaluation"],"pdf":"https://arxiv.org/pdf/2610.34577.pdf","authors":["Zhengxin Zhang","Erkang Zhu","Yin Lin","Claire Cardie","Bolin Ding","Jingren Zhou"],"abstract":"Agent harnesses enable large language models to act through tools, observe the results, and iteratively work toward a task goal. Verification checks and revises agents' work to improve output quality. Yet there is limited guidance on how harnesses should organize this effort. We study verification as an axis of test-time scaling by examining when to intervene, who checks the work, and how checking leads to revision. Our framework spans four layers of the agent lifecycle: initial instructions, mid-turn reminders, completion gates, and independent review. We compare 17 designs across seven frontier coding models on Terminal-Bench (TB) and SWE-bench Verified (SWE), and introduce VisualBench for expert evaluation of visual and interactive artifacts. Initial instructions and execution-time reminders yield modest, model-dependent average gains on the coding benchmarks, without substantially in"},{"upvotes":2,"url":"https://arxiv.org/abs/2610.35450","date":"2026-10-27","topics":["Evaluation"],"title":"OBB-PBD: Extending Parallel Box Decoding to Oriented Bounding Boxes for Referring Expression Grounding in Aerial Imagery","announceDate":"2026-10-27","arxiv":"https://arxiv.org/abs/2610.35450","submittedDate":"2026-10-26","hfUrl":"https://huggingface.co/papers/2610.35450","id":"arxiv:2610.35450","source":"arxiv","tags":["Evaluation"],"pdf":"https://arxiv.org/pdf/2610.35450.pdf","authors":["Chang Woo Song","Yeong Jun Koh"],"abstract":"Referring expression grounding in overhead imagery requires oriented bounding boxes rather than horizontal ones, since aerial objects appear at arbitrary orientations. Most grounding models emit box coordinates sequentially; Parallel Box Decoding (PBD) instead predicts all geometry slots in one forward pass, but only for four-coordinate horizontal boxes. We extend this block-aligned interface to a six-slot oriented representation using a double-angle parameterization. Rather than assuming correctness from a decreasing loss curve, we verify the extension with image/prompt-shuffle controls and visibility/leakage probes, which show that the corrected model depends on both the image and the prompt rather than on prompt statistics alone. On the aerial vehicle visual grounding (AVVG) benchmark, whose targets are genuinely oriented, the extended model improves rotated intersection over union (r"},{"upvotes":1,"url":"https://arxiv.org/abs/2610.33877","date":"2026-10-27","topics":["Evaluation"],"title":"Semantic Concept Steering Breaks the Explanation Drift Loop in Continual Learning","announceDate":"2026-10-27","arxiv":"https://arxiv.org/abs/2610.33877","submittedDate":"2026-10-24","hfUrl":"https://huggingface.co/papers/2610.33877","id":"arxiv:2610.33877","source":"arxiv","tags":["Evaluation"],"pdf":"https://arxiv.org/pdf/2610.33877.pdf","authors":["Yehonatan Elisha","Oren Barkan","Noam Koenigstein"],"abstract":"Catastrophic forgetting in continual learning (CL) manifests not only as accuracy degradation but also as \\emph{explanation drift}: models maintain predictive accuracy while silently shifting attention from diagnostic features to spurious correlations. This work identifies and resolves a previously overlooked structural flaw in explanation-aware CL: pixel-level saliency regularization derives supervision targets from the model's own frozen saliency maps, creating a \\emph{self-referential drift loop} that actively reinforces spurious attention across tasks. We introduce \\textbf{C$^3$L} (Concept-Consistent Continual Learning), which breaks this loop by anchoring regularization to class-consistent semantic concepts (e.g., ``curved beak'', ``striped pattern'') discovered offline, independent of model state, providing (i) target independence from model drift, and (ii) cross-instance semantic "},{"upvotes":0,"url":"https://arxiv.org/abs/2610.34585","date":"2026-10-27","topics":["Agentic RAG","Agentic Search","Post-Training","LLM Training","Reasoning","Hallucination","Evaluation","Fine-tuning"],"title":"Large Language Models: A Plain-Language Overview for Engineers","announceDate":"2026-10-27","arxiv":"https://arxiv.org/abs/2610.34585","submittedDate":"2026-10-25","id":"arxiv:2610.34585","source":"arxiv","tags":["Agentic RAG","Agentic Search","Post-Training","LLM Training","Reasoning"],"pdf":"https://arxiv.org/pdf/2610.34585.pdf","authors":["Bahaeddin Türkoğlu"],"abstract":"Large language models (LLMs) are neural networks trained on huge text collections to generate text by predicting what comes next. Engineers using ChatGPT and other generative artificial intelligence (AI) tools need a clear picture of what training changes and prompts add. The article starts with the Transformer, which connects words in context, and pre-training, where models learn to predict text. It then explains how fine-tuning adapts models to requests, with reinforcement learning from human feedback using human answer rankings. Next, retrieval-augmented generation (RAG) supplies documents, while chain-of-thought prompting encourages intermediate steps and agents use tools. FlashAttention lowers training and running costs by reducing data movement during attention; quantized low-rank adaptation (QLoRA) saves fine-tuning memory. Readers get a life cycle figure and tables comparing meth"},{"upvotes":0,"url":"https://arxiv.org/abs/2610.33451","date":"2026-10-27","topics":["Post-Training","LLM Training","VLM Training","Reasoning","Alignment","Fine-tuning","RL for LLM"],"title":"A Comprehensive Framework for All Stages of Large-Model Training: From Data and Tokenization, through Pretraining, to Post-Training Alignment","announceDate":"2026-10-27","arxiv":"https://arxiv.org/abs/2610.33451","submittedDate":"2026-10-24","id":"arxiv:2610.33451","source":"arxiv","tags":["Post-Training","LLM Training","VLM Training","Reasoning","Alignment"],"pdf":"https://arxiv.org/pdf/2610.33451.pdf","authors":["Xiangjing An","Zhibin Jiao","Aiting Chen"],"abstract":"The capabilities of large language models (LLMs) and multimodal LLMs (MLLMs) arise from the synergy of the full training pipeline, including data and tokenization, pretraining, and post-training (supervised fine-tuning, preference alignment, reinforcement learning, and continual optimization), rather than any individual stage. Existing surveys mostly adopt a single-stage or single-technique perspective, treating related research as isolated systems without unified stage division or a horizontally comparable basis. This paper proposes a unified stage division and a six-dimensional analytical framework covering data, objective function, optimization strategy, system constraints, evaluation, and risk and governance. We systematically review 395 core references from 2017 to 2026, and present a conceptual map of cross-stage effects: forward constraints of pretraining on post-training, and rev"},{"upvotes":0,"url":"https://arxiv.org/abs/2610.34609","date":"2026-10-27","topics":["Post-Training","LLM Training","VLM Training","Reasoning","Evaluation","Fine-tuning","RL for LLM"],"title":"Audio-R1: Audio Reasoning through Reinforcement Learning on Self-Supervised Tasks","announceDate":"2026-10-27","arxiv":"https://arxiv.org/abs/2610.34609","submittedDate":"2026-10-25","id":"arxiv:2610.34609","source":"arxiv","tags":["Post-Training","LLM Training","VLM Training","Reasoning","Evaluation"],"pdf":"https://arxiv.org/pdf/2610.34609.pdf","authors":["Jihoon Jeong","Mirco Ravanelli","Zhepei Wang","Cem Subakan"],"abstract":"Reasoning is increasingly important for large audio-language models (LALMs), yet remains relatively underexplored compared with text-only and vision-language models. We introduce Audio-R1, a reinforcement learning (RL) post-training framework that revisits audio self-supervised learning as a source of verifiable rewards for improving audio understanding and reasoning task performance. Audio-R1 uses answers automatically determined during the construction of self-supervised tasks to verify model responses and compute rewards. Experiments across multiple LALMs and diverse audio benchmarks show consistent performance gains, while ablations demonstrate the benefits of each self-supervised task and additional gains from joint training. While both supervised fine-tuning and Audio-R1 improve self-supervised task accuracy, Audio-R1 further improves performance on downstream tasks distinct from t"}],"archive":[],"latestPath":"data/latest.json"};
